// Copyright (c) 2026 Roshan. All rights reserved.package com.roshan.persona.telemetryimport com.roshan.persona.common.CorrelationIdimport java.util.concurrent.ConcurrentHashMapimport java.util.concurrent.atomic.AtomicLongimport java.util.concurrent.atomic.LongAdderimport javax.inject.Injectimport javax.inject.Singletonimport kotlin.math.maximport kotlin.math.min/** * NOUS — Metrics recorder. * * Lightweight in-memory metrics aggregator with three metric types: *   - [Counter] — monotonically increasing value (e.g., brain.layer.invocation count) *   - [Histogram] — distribution of values (e.g., LLM inference latency p50/p95/p99) *   - [Gauge] — current value at any time (e.g., memory.usage.bytes) * * Metrics are aggregated in-memory and periodically flushed to: *   - Room (local history, for in-app dashboard) *   - Optional OpenTelemetry export (user opt-in) * * Tag-based: every metric carries tags (e.g., `layer=intent`, `provider=openai`). * High-cardinality tags (user IDs, prompt contents) are forbidden — would blow * up memory. * * Inspired by Prometheus + OpenTelemetry, but zero-dependency for offline use. */@Singletonclass MetricsRecorder @Inject constructor() {    private val counters = ConcurrentHashMap<CounterKey, LongAdder>()    private val histograms = ConcurrentHashMap<HistogramKey, Histogram>()    private val gauges = ConcurrentHashMap<String, AtomicLong>()    // ─── Counter ───────────────────────────────────────────────────────────    /** Increment a counter by 1. */    fun incrementCounter(name: String, vararg tags: Pair<String, String>) {        incrementCounter(name, 1L, *tags)    }    /** Increment a counter by [amount]. */    fun incrementCounter(name: String, amount: Long, vararg tags: Pair<String, String>) {        val key = CounterKey(name, tags.toMap())        counters.computeIfAbsent(key) { LongAdder() }.add(amount)    }    /** Snapshot all counters. Returns map of `name{tag1=v1,tag2=v2}` → value. */    fun snapshotCounters(): Map<String, Long> = counters        .mapKeys { (key, _) -> key.toPrometheusString() }        .mapValues { (_, adder) -> adder.sum() }    // ─── Histogram ─────────────────────────────────────────────────────────    /** Record a value into a histogram. */    fun recordHistogram(name: String, value: Long, vararg tags: Pair<String, String>) {        val key = HistogramKey(name, tags.toMap())        histograms.computeIfAbsent(key) { Histogram() }.record(value)    }    /** Snapshot histogram percentiles. */    fun snapshotHistograms(): Map<String, HistogramSnapshot> = histograms        .mapKeys { (key, _) -> key.toPrometheusString() }        .mapValues { (_, hist) -> hist.snapshot() }    // ─── Gauge ─────────────────────────────────────────────────────────────    /** Set the current value of a gauge. */    fun setGauge(name: String, value: Long) {        gauges.computeIfAbsent(name) { AtomicLong() }.set(value)    }    /** Snapshot all gauges. */    fun snapshotGauges(): Map<String, Long> = gauges        .mapValues { (_, atomic) -> atomic.get() }    // ─── Reset (for testing) ───────────────────────────────────────────────    fun reset() {        counters.clear()        histograms.clear()        gauges.clear()    }    // ─── Trace helpers ─────────────────────────────────────────────────────    /**     * Time a suspending block, recording its duration in a histogram.     * Returns the block's result. Records under `name` with the given tags.     */    suspend fun <T> trace(        name: String,        correlationId: CorrelationId = CorrelationId.generate(),        vararg tags: Pair<String, String>,        block: suspend () -> T,    ): T {        val startNanos = System.nanoTime()        return try {            block()        } finally {            val durationMs = (System.nanoTime() - startNanos) / 1_000_000            val allTags = tags.toList() + ("correlationId" to correlationId.value)            recordHistogram(name, durationMs, *allTags.toTypedArray())        }    }    /** Variant of [trace] that doesn't suspend (for synchronous blocks). */    inline fun <T> traceSync(        name: String,        vararg tags: Pair<String, String>,        block: () -> T,    ): T {        val startNanos = System.nanoTime()        return try {            block()        } finally {            val durationMs = (System.nanoTime() - startNanos) / 1_000_000            recordHistogram(name, durationMs, *tags)        }    }}// ─── Internal: keys & histogram bucket ──────────────────────────────────────internal data class CounterKey(val name: String, val tags: Map<String, String>) {    fun toPrometheusString(): String = buildString {        append(name)        if (tags.isNotEmpty()) {            append("{")            append(tags.entries.joinToString(",") { "${it.key}=\"${it.value}\"" })            append("}")        }    }}internal data class HistogramKey(val name: String, val tags: Map<String, String>) {    fun toPrometheusString(): String = CounterKey(name, tags).toPrometheusString()}internal class Histogram {    private val count = LongAdder()    private val sum = LongAdder()    private val min = AtomicLong(Long.MAX_VALUE)    private val max = AtomicLong(Long.MIN_VALUE)    // Simplified bucketing: track all samples (sufficient for low-volume metrics)    // For high-volume, replace with t-digest or HdrHistogram.    private val samples = mutableListOf<Long>()    @Synchronized    fun record(value: Long) {        count.increment()        sum.add(value)        min.updateAndGet { cur -> if (cur == Long.MAX_VALUE) value else min(cur, value) }        max.updateAndGet { cur -> if (cur == Long.MIN_VALUE) value else max(cur, value) }        if (samples.size < 10_000) samples.add(value)    }    @Synchronized    fun snapshot(): HistogramSnapshot {        val sorted = samples.sorted()        return HistogramSnapshot(            count = count.sum(),            sum = sum.sum(),            min = if (min.get() == Long.MAX_VALUE) 0 else min.get(),            max = if (max.get() == Long.MIN_VALUE) 0 else max.get(),            p50 = percentile(sorted, 0.50),            p95 = percentile(sorted, 0.95),            p99 = percentile(sorted, 0.99),        )    }    private fun percentile(sorted: List<Long>, p: Double): Long {        if (sorted.isEmpty()) return 0        val idx = ((sorted.size - 1) * p).toInt().coerceIn(0, sorted.size - 1)        return sorted[idx]    }}/** Read-only histogram snapshot — used by dashboards + OpenTelemetry export. */data class HistogramSnapshot(    val count: Long,    val sum: Long,    val min: Long,    val max: Long,    val p50: Long,    val p95: Long,    val p99: Long,)